     m_axis_tvalid, m_axis_tready, m_axis_tlast, m_axis_tuser, cfg_wr,
     cfg_rd, cfg_addr, cfg_wdata, cfg_rdata, verdict_valid,
     verdict_mal);
  input clk, rst, s_axis_tvalid, s_axis_tlast, s_axis_tuser,
       m_axis_tready, cfg_wr, cfg_rd;
  input [7:0] s_axis_tdata;
  input [9:0] cfg_addr;
  input [31:0] cfg_wdata;
  output s_axis_tready, m_axis_tvalid, m_axis_tlast, m_axis_tuser,
       verdict_valid, verdict_mal;
  output [7:0] m_axis_tdata;
  output [31:0] cfg_rdata;
  wire clk, rst, s_axis_tvalid, s_axis_tlast, s_axis_tuser,
       m_axis_tready, cfg_wr, cfg_rd;
  wire [7:0] s_axis_tdata;
  wire [9:0] cfg_addr;
  wire [31:0] cfg_wdata;
  wire s_axis_tready, m_axis_tvalid, m_axis_tlast, m_axis_tuser,
       verdict_valid, verdict_mal;
  wire [7:0] m_axis_tdata;
  wire [31:0] cfg_rdata;
  wire UNCONNECTED15, UNCONNECTED16;
  assign m_axis_tuser = 1'b0;
  assign s_axis_tready = 1'b1;
  snn_pkt_filter_BUF_AW11 u_filter(.clk (clk), .rst (rst),
