       .s_axis_tready (UNCONNECTED15), .s_axis_tlast (s_axis_tlast),
       .s_axis_tuser (s_axis_tuser), .m_axis_tdata (m_axis_tdata),
       .m_axis_tvalid (m_axis_tvalid), .m_axis_tready (m_axis_tready),
       .m_axis_tlast (m_axis_tlast), .m_axis_tuser (UNCONNECTED16),
       .cfg_wr (cfg_wr), .cfg_rd (cfg_rd), .cfg_addr (cfg_addr),
       .cfg_wdata (cfg_wdata), .cfg_rdata (cfg_rdata), .verdict_valid
